package com.cpf.batch.centercut.runner; import com.cpf.batch.api.ActualState; import com.cpf.batch.centercut.runner.internal.*; import com.cpf.batch.runtime.RuntimeStateProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.Duration; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*;
@Component public class CenterCutRuntime implements RuntimeStateProvider,AutoCloseable { private final JdbcCenterCutClaimRepository repo;private final CenterCutDispatcher dispatcher;private final String id,pool;private final Duration duration;private final ExecutorService executor=Executors.newVirtualThreadPerTaskExecutor();private final AtomicBoolean draining=new AtomicBoolean();private final AtomicReference<JdbcCenterCutClaimRepository.Claim> current=new AtomicReference<>();public CenterCutRuntime(JdbcCenterCutClaimRepository r,CenterCutDispatcher d,@Value("${cpf.center-cut.runner-id:${CPF_INSTANCE_ID:center-cut-local-01}}")String i,@Value("${cpf.center-cut.pool:center-cut}")String p,@Value("${cpf.center-cut.lease-seconds:30}")long s){repo=r;dispatcher=d;id=i;pool=p;duration=Duration.ofSeconds(Math.max(10,s));}@Scheduled(fixedDelayString="${cpf.center-cut.recovery-ms:5000}") public void recover(){repo.recoverExpiredToUnknown();}
 @Scheduled(fixedDelayString="${cpf.center-cut.poll-ms:500}") public void poll(){if(draining.get()||current.get()!=null)return;repo.claim(id,pool,duration).ifPresent(c->{current.set(c);executor.submit(()->{try{dispatcher.execute(c);}finally{current.compareAndSet(c,null);}});});}@Scheduled(fixedDelayString="${cpf.center-cut.heartbeat-ms:5000}") public void renew(){var c=current.get();if(c!=null&&!repo.renew(c,duration))current.compareAndSet(c,null);}public void drain(){draining.set(true);}public void resume(){draining.set(false);}public ActualState actualState(){return draining.get()?ActualState.DRAINING:(current.get()==null?ActualState.READY:ActualState.BUSY);}public List<String> currentExecutions(){return current.get()==null?List.of():List.of(Long.toString(current.get().itemId()));}public List<String> activeLeases(){return current.get()==null?List.of():List.of(current.get().claimToken());}public boolean draining(){return draining.get();}public long fencingToken(){return current.get()==null?0:current.get().fencingToken();}public void close(){executor.shutdown();} }
